package com.openfoodfacts.mcp;

import io.modelcontextprotocol.spec.McpSchema.CallToolResult;
import org.springframework.ai.mcp.annotation.McpTool;
import org.springframework.ai.mcp.annotation.McpToolParam;
import org.springframework.stereotype.Component;
import java.util.*;

@Component
public class FoodTools {
    private final OffClient off; private final NutritionService nutrition;
    public FoodTools(OffClient off,NutritionService nutrition){this.off=off;this.nutrition=nutrition;}
    private CallToolResult result(String text,Map<String,Object> data,boolean error){var b=CallToolResult.builder().addTextContent(text).isError(error);if(data!=null)b.structuredContent(data);return b.build();}
    private CallToolResult fail(String msg){return result(msg,null,true);}
    private String barcode(String raw){if(raw==null)return null;String s=raw.trim();if(s.length()<4||s.length()>30||!s.matches("[0-9\\s-]+"))return null;s=s.replaceAll("[\\s-]","");return s.length()>=4 && s.length()<=30 && s.matches("[0-9]+")?s:null;}
    private Product product(String raw){String b=barcode(raw);return b==null?null:off.byBarcode(b);}
    private CallToolResult missing(String raw){return fail("Product with barcode \""+raw+"\" was not found in the Open Food Facts database.");}
    private CallToolResult unexpected(String operation,RuntimeException e){return fail("Unable to "+operation+": "+(e.getMessage()==null?"Please try again later.":e.getMessage()));}
    @McpTool(name="get_product_by_barcode",description="Look up a food product by its barcode (EAN-13, UPC-A, or other standard barcode). Returns product name, brand, ingredients, nutrition, Nutri-Score, NOVA group, allergens, and other key information.")
    public CallToolResult getProduct(@McpToolParam(description="Numeric product barcode, 4 to 30 characters",required=true) String barcode){String code=barcode(barcode);if(code==null)return fail("Invalid barcode. Please provide a valid numeric barcode (4-30 characters).");try{Product p=off.byBarcode(code);if(p==null)return missing(code);Map<String,Object> n=nutrition.nutrition(p);var lines=new ArrayList<String>();lines.add("Product: "+p.product_name());if(!p.brands().isBlank())lines.add("Brand: "+p.brands());if(!p.quantity().isBlank())lines.add("Quantity: "+p.quantity());if(!p.categories().isBlank())lines.add("Categories: "+p.categories());if(!p.nutrition_grades().isBlank())lines.add("Nutri-Score: "+p.nutrition_grades().toUpperCase());if(p.nova_group()!=null)lines.add("NOVA Group: "+p.nova_group());if(p.nutrient("energy_kcal_100g")!=null)lines.add("Calories: "+p.nutrient("energy_kcal_100g")+" kcal/100g");if(!p.allergens().isBlank())lines.add("Allergens: "+p.allergens());return result(String.join("\n",lines),map("barcode",p.barcode(),"product_name",p.product_name(),"brands",p.brands(),"quantity",p.quantity(),"categories",p.categories(),"labels",p.labels(),"ingredients_text",p.ingredients_text(),"allergens",p.allergens(),"traces",p.traces(),"nutrition_summary",n,"image_url",p.image_url(),"image_front_url",p.image_front_url(),"countries",p.countries(),"stores",p.stores()),false);}catch(RuntimeException e){return unexpected("retrieve product information",e);}}
    @McpTool(name="search_products",description="Search Open Food Facts by product name, brand, or description. Results are paginated; use page to fetch additional results.")
    public CallToolResult search(@McpToolParam(description="Search terms, 1 to 200 characters",required=true) String query,@McpToolParam(description="Page number; defaults to 1",required=false) Integer page,@McpToolParam(description="Results per page, maximum 50; defaults to 10",required=false) Integer page_size){String q=query==null?"":query.trim();if(q.isEmpty()||q.length()>200)return fail("Invalid search query. Please provide a query between 1 and 200 characters.");int pg=Math.max(1,Math.min(page==null?1:page,100)),size=Math.max(1,Math.min(page_size==null?10:page_size,50));try{Map<String,Object> data=off.search(q,pg,size);@SuppressWarnings("unchecked") List<Product> ps=(List<Product>)data.get("products");if(ps.isEmpty())return result("No products found for \""+q+"\". Try different search terms or check the spelling.",map("query",q,"total_count",0,"page",pg,"page_size",size,"products",List.of()),false);var entries=new ArrayList<Map<String,Object>>();var lines=new ArrayList<String>();int i=1;for(Product p:ps){lines.add(i+++". "+p.product_name()+(p.brands().isBlank()?"":"\n   Brand: "+p.brands())+"\n   Barcode: "+p.barcode()+(p.nutrition_grades().isBlank()?"":"\n   Nutri-Score: "+p.nutrition_grades().toUpperCase()));entries.add(map("barcode",p.barcode(),"product_name",p.product_name(),"brands",p.brands(),"quantity",p.quantity(),"nutriscore_grade",p.nutrition_grades().isBlank()?"unknown":p.nutrition_grades(),"nova_group",p.nova_group(),"categories",p.categories(),"image_front_url",p.image_front_url()));}return result("Found "+data.get("count")+" products for \""+q+"\" (showing page "+pg+"):\n\n"+String.join("\n\n",lines),map("query",q,"total_count",data.get("count"),"page",data.get("page"),"page_size",data.get("page_size"),"page_count",data.get("page_count"),"products",entries),false);}catch(RuntimeException e){return unexpected("search products",e);}}
    @McpTool(name="get_nutrition_info",description="Get detailed nutrition for a product barcode, including Nutri-Score, NOVA, Eco-Score, calories, nutrient levels, and health highlights.")
    public CallToolResult nutrition(@McpToolParam(description="Numeric product barcode",required=true) String barcode){String code=barcode(barcode);if(code==null)return fail("Invalid barcode. Please provide a valid numeric barcode.");try{Product p=off.byBarcode(code);if(p==null)return fail("Product with barcode \""+code+"\" was not found. The product may not be in the Open Food Facts database.");Map<String,Object> n=nutrition.nutrition(p);var lines=new ArrayList<String>();lines.add("Nutrition Info for: "+p.product_name());if(!p.brands().isBlank())lines.add("Brand: "+p.brands());lines.add("Nutri-Score: "+String.valueOf(n.get("nutriscore_grade")).toUpperCase());if(n.get("nova_group")!=null)lines.add("NOVA Group: "+n.get("nova_group"));lines.add("Eco-Score: "+String.valueOf(n.get("ecoscore_grade")).toUpperCase());if(n.get("calories_per_100g")!=null)lines.add("Calories: "+n.get("calories_per_100g")+" kcal per 100g");var nutrientLines=new ArrayList<String>();for(Map<String,Object> item:(List<Map<String,Object>>)n.get("key_nutrients"))if(item.get("value_per_100g")!=null)nutrientLines.add("  • "+item.get("name")+": "+item.get("value_per_100g")+item.get("unit")+"/100g ("+item.get("level")+")");if(!nutrientLines.isEmpty())lines.add("\nNutrients per 100g:\n"+String.join("\n",nutrientLines));var highlights=(List<String>)n.get("health_highlights");if(!highlights.isEmpty())lines.add("\nHealth Highlights:\n  ⚡ "+String.join("\n  ⚡ ",highlights));return result(String.join("\n",lines),merge(map("barcode",p.barcode(),"product_name",p.product_name(),"brands",p.brands(),"quantity",p.quantity()),n),false);}catch(RuntimeException e){return unexpected("retrieve nutrition information",e);}}
    @McpTool(name="check_dietary_preferences",description="Check vegetarian, vegan, gluten-free, and dairy-free suitability based on product ingredients and labels. Verify the actual packaging.")
    public CallToolResult dietary(@McpToolParam(description="Numeric product barcode",required=true) String barcode){String c=barcode(barcode);if(c==null)return fail("Invalid barcode. Please provide a valid numeric barcode.");try{Product p=off.byBarcode(c);if(p==null)return missing(c);Map<String,Object>a=nutrition.dietary(p);var lines=new ArrayList<String>();lines.add("Dietary Analysis for: "+p.product_name());for(String k:List.of("is_vegetarian","is_vegan","is_gluten_free","is_dairy_free")){Object v=a.get(k);lines.add(k.substring(3).replace('_',' ')+": "+(v==null?"Unknown":Boolean.TRUE.equals(v)?"Yes":"No"));}lines.add("Confidence: "+a.get("confidence"));for(String note:(List<String>)a.get("notes"))lines.add("Note: "+note);return result(String.join("\n",lines),map("barcode",c,"product_name",p.product_name(),"brands",p.brands(),"dietary_analysis",a),false);}catch(RuntimeException e){return unexpected("analyze dietary preferences",e);}}
    @McpTool(name="check_allergens",description="Check product allergens and potential traces. This is an informational analysis; always verify actual packaging, especially for severe allergies.")
    public CallToolResult allergens(@McpToolParam(description="Numeric product barcode",required=true) String barcode){String c=barcode(barcode);if(c==null)return fail("Invalid barcode. Please provide a valid numeric barcode.");try{Product p=off.byBarcode(c);if(p==null)return missing(c);Map<String,Object>a=nutrition.allergens(p);return result("Allergen Report for: "+p.product_name()+"\nDetected Allergens: "+String.join(", ",(List<String>)a.get("detected_allergens"))+"\nPotential Traces (May Contain): "+String.join(", ",(List<String>)a.get("potential_traces"))+"\nConfidence: "+a.get("confidence")+"\n\n⚠️ "+a.get("disclaimer"),map("barcode",c,"product_name",p.product_name(),"brands",p.brands(),"allergen_report",a),false);}catch(RuntimeException e){return unexpected("check allergens",e);}}
    @McpTool(name="analyze_ingredients",description="Explain ingredients, identify additives and E-numbers, and flag potential allergens in a product ingredient list.")
    public CallToolResult ingredients(@McpToolParam(description="Numeric product barcode",required=true) String barcode){String c=barcode(barcode);if(c==null)return fail("Invalid barcode. Please provide a valid numeric barcode.");try{Product p=off.byBarcode(c);if(p==null)return missing(c);Map<String,Object>a=nutrition.ingredients(p);return result("Ingredient Analysis for: "+p.product_name()+"\nIngredients: "+(p.ingredients_text().isBlank()?"No ingredient information available.":p.ingredients_text())+"\n"+String.join("\n",(List<String>)a.get("explanation")),map("barcode",c,"product_name",p.product_name(),"brands",p.brands(),"ingredient_analysis",a),false);}catch(RuntimeException e){return unexpected("analyze ingredients",e);}}
    @McpTool(name="compare_products",description="Compare 2 to 5 food products by barcode. Criteria: overall, sugar, fat, protein, or calories.")
    public CallToolResult compare(@McpToolParam(description="Two to five numeric product barcodes",required=true) List<String> barcodes,@McpToolParam(description="overall, sugar, fat, protein, or calories; defaults to overall",required=false) String criteria){if(barcodes==null||barcodes.size()<2||barcodes.size()>5)return fail("Please provide between 2 and 5 barcodes to compare.");var codes=new ArrayList<String>();for(String b:barcodes){String c=barcode(b);if(c==null)return fail("Invalid barcode: \""+b+"\". All barcodes must be valid numeric strings.");codes.add(c);}String cr=criteria==null||criteria.isBlank()?"overall":criteria;if(!List.of("overall","sugar","fat","protein","calories").contains(cr))return fail("Invalid comparison criteria.");try{var products=new ArrayList<Product>();var absent=new ArrayList<String>();for(String c:codes){Product p=off.byBarcode(c);if(p==null)absent.add(c);else products.add(p);}if(products.size()<2)return fail("Not enough products found to compare. Products not found: "+String.join(", ",absent));Map<String,Object> comp=nutrition.comparison(products,cr);var rows=new ArrayList<String>();int i=1;for(Map<String,Object> row:(List<Map<String,Object>>)comp.get("products")){rows.add(i+++". "+row.get("product_name")+" ("+row.get("barcode")+")\n   Nutri-Score: "+String.valueOf(row.get("nutriscore_grade")).toUpperCase()+" | NOVA: "+shown(row.get("nova_group"))+"\n   Cal: "+shown(row.get("calories_per_100g"))+"kcal | Sugar: "+shown(row.get("sugar_per_100g"))+"g | Fat: "+shown(row.get("fat_per_100g"))+"g | Protein: "+shown(row.get("protein_per_100g"))+"g | Salt: "+shown(row.get("salt_per_100g"))+"g");}String note=absent.isEmpty()?"":"\n\nNote: Products not found (excluded from comparison): "+String.join(", ",absent);return result("Product Comparison (by "+cr+"):\n\n"+String.join("\n\n",rows)+"\n\n🏆 "+comp.get("recommendation")+note,map("comparison",comp,"not_found_barcodes",absent),false);}catch(RuntimeException e){return unexpected("compare products",e);}}
    @McpTool(name="find_alternatives",description="Find healthier alternatives to a product within its most specific category, sorted by overall Nutri-Score, sugar, fat, salt, or calories.")
    public CallToolResult alternatives(@McpToolParam(description="Numeric barcode of the original product",required=true) String barcode,@McpToolParam(description="overall, sugar, fat, salt, or calories; defaults to overall",required=false) String criteria,@McpToolParam(description="Number of results, 1 to 10; defaults to 5",required=false) Integer max_results){String c=barcode(barcode);if(c==null)return fail("Invalid barcode. Please provide a valid numeric barcode.");String cr=criteria==null||criteria.isBlank()?"overall":criteria;if(!List.of("overall","sugar","fat","salt","calories").contains(cr))return fail("Invalid alternative criteria.");int max=Math.max(1,Math.min(max_results==null?5:max_results,10));try{Product p=off.byBarcode(c);if(p==null)return fail("Product with barcode \""+c+"\" was not found. Cannot find alternatives without the original product.");String[] cats=p.categories().split(",");if(p.categories().isBlank())return result("No category information available for "+p.product_name()+". Unable to find alternatives in the same category.",map("original_barcode",c,"original_product_name",p.product_name(),"alternatives",List.of(),"message","No category data available."),false);String cat=cats[cats.length-1].trim();Map<String,Object> sr=off.category(cat,1,50);@SuppressWarnings("unchecked") List<Product> found=(List<Product>)sr.get("products");var candidates=new ArrayList<>(found.stream().filter(x->!x.barcode().equals(c)&&!x.product_name().equals("Unknown")).toList());Comparator<Product> cmp=switch(cr){case"sugar"->Comparator.comparingDouble(x->val(x,"sugars_100g"));case"fat"->Comparator.comparingDouble(x->val(x,"fat_100g"));case"salt"->Comparator.comparingDouble(x->val(x,"salt_100g"));case"calories"->Comparator.comparingDouble(x->val(x,"energy_kcal_100g"));default->Comparator.comparingInt(x->{int i=List.of("a","b","c","d","e").indexOf(x.nutrition_grades().toLowerCase());return i<0?6:i;});};candidates.sort(cmp);var alts=new ArrayList<Map<String,Object>>();for(Product a:candidates.stream().limit(max).toList())alts.add(map("barcode",a.barcode(),"product_name",a.product_name(),"brands",a.brands(),"nutriscore_grade",a.nutrition_grades().isBlank()?"unknown":a.nutrition_grades(),"nova_group",a.nova_group(),"sugar_per_100g",a.nutrient("sugars_100g"),"fat_per_100g",a.nutrient("fat_100g"),"salt_per_100g",a.nutrient("salt_100g"),"calories_per_100g",a.nutrient("energy_kcal_100g"),"image_front_url",a.image_front_url()));if(alts.isEmpty())return result("No alternatives found for "+p.product_name()+" in the \""+cat+"\" category.",map("original_barcode",c,"original_product_name",p.product_name(),"category_searched",cat,"alternatives",List.of()),false);var descriptions=new ArrayList<String>();int rank=1;for(Product alt:candidates.stream().limit(max).toList()){var row=new ArrayList<String>();row.add(rank+++". "+alt.product_name());if(!alt.brands().isBlank())row.add("   Brand: "+alt.brands());row.add("   Barcode: "+alt.barcode());if(!alt.nutrition_grades().isBlank())row.add("   Nutri-Score: "+alt.nutrition_grades().toUpperCase());if(alt.nutrient("sugars_100g")!=null)row.add("   Sugar: "+alt.nutrient("sugars_100g")+"g/100g");if(alt.nutrient("fat_100g")!=null)row.add("   Fat: "+alt.nutrient("fat_100g")+"g/100g");if(alt.nutrient("energy_kcal_100g")!=null)row.add("   Calories: "+alt.nutrient("energy_kcal_100g")+" kcal/100g");descriptions.add(String.join("\n",row));}return result("Alternatives to: "+p.product_name()+" ("+(p.nutrition_grades().isBlank()?"?":p.nutrition_grades().toUpperCase())+")\nCategory: "+cat+"\nSorted by: "+cr+"\n\n"+String.join("\n\n",descriptions),map("original_barcode",c,"original_product_name",p.product_name(),"original_nutriscore",p.nutrition_grades().isBlank()?"unknown":p.nutrition_grades(),"category_searched",cat,"criteria_used",cr,"alternatives",alts),false);}catch(RuntimeException e){return unexpected("find alternatives",e);}}
    private static String shown(Object value){if(value==null)return "?";if(value instanceof Double d && d==Math.rint(d))return Long.toString(d.longValue());return value.toString();}
    private double val(Product p,String k){Double d=p.nutrient(k);return d==null?999:d;}
    private static Map<String,Object> map(Object...v){var m=new LinkedHashMap<String,Object>();for(int i=0;i<v.length;i+=2)m.put((String)v[i],v[i+1]);return m;}
    private static Map<String,Object> merge(Map<String,Object>a,Map<String,Object>b){var m=new LinkedHashMap<>(a);m.putAll(b);return m;}
}
